import { ICON_COLORS } from "./brand-resources";

/**
 * The downloadable icon library. Glyphs come from the Figma Icon Library (Slide Skill 2.0,
 * node 18:782) and live in icon-glyphs.json, generated by scripts/icon-library/build-glyphs.mjs.
 * Colors and treatments follow the Figma Icon Tile specs (27:782 light, 32:803 dark).
 */
export type IconSurface = "light" | "dark";
export type IconTreatment = "plain" | "tinted" | "solid";
export type IconFormat = "svg" | "png";
export type IconColor = (typeof ICON_COLORS)[IconSurface][number];
export type IconGlyph = { name: string; d: string; rule?: string };
export type IconCategory = { id: string; name: string; icons: IconGlyph[] };
export type IconLibraryData = { source: string; license: string; categories: IconCategory[] };
export type IconStyle = { surface: IconSurface; color: IconColor; treatment: IconTreatment };

