/** Solid tiles use white ink on the light set and Midnight ink on the dark set (white disappears there). */
export function solidInk(surface: IconSurface) {
  return surface === "light" ? WHITE : MIDNIGHT;
}

export function iconColors(surface: IconSurface): readonly IconColor[] {
  return ICON_COLORS[surface];
}

export function slug(value: string) {
  return value.toLowerCase().replace(/&/g, "and").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

export function iconLabel(name: string) {
  return name.replace(/_/g, " ");
}

export function styleSlug({ surface, color, treatment }: IconStyle) {
  return `${surface}_${slug(color.name)}_${treatment}`;
}

export function iconFilename(name: string, style: IconStyle, format: IconFormat) {
  return `og-icon_${name}_${styleSlug(style)}.${format}`;
}

/** `scope` is "all", "search", or a category id. */
export function iconZipFilename(scope: string, style: IconStyle, format: IconFormat) {
  return `ordergroove-icons_${scope}_${styleSlug(style)}_${format}.zip`;
}

