export function matchesIconQuery(icon: IconGlyph, category: IconCategory, query: string) {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return true;
  const haystack = `${iconLabel(icon.name)} ${icon.name} ${category.name} ${ICON_ALIASES[icon.name] ?? ""}`.toLowerCase();
  return words.every((word) => haystack.includes(word));
}

let glyphRequest: Promise<IconLibraryData> | null = null;

/** Loads the glyph data in its own chunk, so the hub only fetches it when the library mounts. */
export function loadIconLibrary(): Promise<IconLibraryData> {
  glyphRequest ??= import("./icon-glyphs.json").then((module) => module.default as IconLibraryData).catch((error) => {
    glyphRequest = null;
    throw error;
  });
  return glyphRequest;
}
